import { Component, OnInit, OnDestroy, HostListener } from '@angular/core';
import { Router, ActivatedRoute } from '@angular/router';
import { AssetService } from '../../services/asset.service';

export interface IssueRecord {
  assetName:    string;
  assetCategory: string;
  issueDate:    string;
  receiverName: string;
  receiverType: string;
}

const PAGE_SIZE = 10;

@Component({
  selector: 'app-issue-asset',
  templateUrl: './issue-asset.component.html',
  styleUrls: ['./issue-asset.component.scss'],
})
export class IssueAssetComponent implements OnInit, OnDestroy {

  // ── Asset info from query params ─────────────────────────────────────────
  assetId       = '';
  assetName     = '';
  assetTag      = '';
  assetModel    = '';
  assetCategory = '';

  // ── Form fields ──────────────────────────────────────────────────────────
  model              = '';
  assetNameInput     = '';
  status             = '';
  issueTo            = 'User';
  selectedUser       = '';
  issueDate          = '';
  expectedReturn     = '';
  expectedReturnTime = '';
  notes              = '';

  // ── Dropdown options ─────────────────────────────────────────────────────
  statuses = ['Ready to Deploy', 'Deployed', 'Under Maintenance', 'Retired'];
  users    = ['Amal Martin', 'Kurian George', 'Melbin Joseph', 'Mariyan', 'Joyal Saji', 'Dewang', 'Riya Thomas'];

  // ── UI state ─────────────────────────────────────────────────────────────
  statusOpen   = false;
  userOpen     = false;
  showSuccess  = false;
  submitted    = false;
  sidebarOpen  = false;

  // ── Issue log ────────────────────────────────────────────────────────────
  issueLog:      IssueRecord[] = [];
  isLoadingLog   = true;
  logError:      string | null = null;
  searchQuery    = '';
  currentPage    = 1;
  totalPages     = 1;
  totalRecords   = 0;

  get filteredLog(): IssueRecord[] {
    if (!this.searchQuery.trim()) return this.issueLog;
    const q = this.searchQuery.toLowerCase();
    return this.issueLog.filter(r =>
      r.assetName.toLowerCase().includes(q)
      || r.assetCategory.toLowerCase().includes(q)
      || r.receiverName.toLowerCase().includes(q)
      || r.receiverType.toLowerCase().includes(q)
    );
  }

  get pageNumbers(): number[] {
    const pages: number[] = [];
    for (let i = 1; i <= this.totalPages; i++) {
      if (i === 1 || i === this.totalPages || Math.abs(i - this.currentPage) <= 1) pages.push(i);
      else if (pages[pages.length - 1] !== -1) pages.push(-1);
    }
    return pages;
  }

  constructor(
    private router: Router,
    private route: ActivatedRoute,
    private assetService: AssetService
  ) {}

  ngOnInit(): void {
    this.route.queryParams.subscribe((params: Record<string, string>) => {
      if (params['assetId'])       this.assetId       = params['assetId'];
      if (params['assetName'])     this.assetName     = params['assetName'];
      if (params['assetTag'])      this.assetTag      = params['assetTag'];
      if (params['assetModel'])    this.assetModel    = params['assetModel'];
      if (params['assetCategory']) this.assetCategory = params['assetCategory'];
    });

    this.loadIssueLog();
  }

  ngOnDestroy(): void {}

  private loadIssueLog(): void {
    this.isLoadingLog = true;
    this.logError     = null;

    this.assetService.getIssuedAssets(this.currentPage, PAGE_SIZE).subscribe({
      next: (response: any) => {
        const data = response?.responseData?.data ?? {};
        const raw: any[] = data.assets ?? [];

        this.totalRecords = data.totalRecords ?? raw.length;
        this.totalPages   = data.totalPages   ?? 1;
        this.currentPage  = data.currentPage  ?? this.currentPage;

        this.issueLog = raw.map(item => ({
          assetName:    item.assetName     ?? '—',
          assetCategory: item.assetCategory ?? '—',
          issueDate:    item.issueDate
            ? new Date(item.issueDate).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' })
            : '—',
          receiverName: item.receiverName  ?? '—',
          receiverType: item.receiverType  ?? '—',
        }));

        this.isLoadingLog = false;
      },
      error: (err: any) => {
        console.error('Failed to load issue log:', err);
        this.logError = 'Could not load issue log from server.';
        this.isLoadingLog = false;
      }
    });
  }

  prevPage(): void { if (this.currentPage > 1) { this.currentPage--; this.loadIssueLog(); } }
  nextPage(): void { if (this.currentPage < this.totalPages) { this.currentPage++; this.loadIssueLog(); } }
  goToPage(p: number): void { if (p !== this.currentPage) { this.currentPage = p; this.loadIssueLog(); } }

  getReceiverTypeClass(type: string): string {
    const map: Record<string, string> = {
      'Location': 'bg-blue-50 text-blue-700',
      'Asset':    'bg-purple-50 text-purple-700',
      'Person':   'bg-green-50 text-green-700',
    };
    return map[type] ?? 'bg-slate-50 text-slate-600';
  }

  @HostListener('document:click')
  onDocumentClick(): void { this.sidebarOpen = false; this.statusOpen = false; this.userOpen = false; }

  goBack(): void         { this.router.navigate(['/assets/view']); }
  goToDashboard(): void  { this.router.navigate(['/']); }
  goToViewAssets(): void { this.router.navigate(['/assets/view']); }
  goToIssueLog(): void   { this.router.navigate(['/assets/issue-log']); }
  goToReturnLog(): void  { this.router.navigate(['/assets/return-log']); }
  goToReports(): void    { this.router.navigate(['/assets/reports']); }

  onSubmit(): void {
    this.submitted   = true;
    this.showSuccess = true;
  }

  issueAnother(): void {
    this.showSuccess        = false;
    this.submitted          = false;
    this.model              = '';
    this.assetNameInput     = '';
    this.status             = '';
    this.selectedUser       = '';
    this.issueDate          = '';
    this.expectedReturn     = '';
    this.expectedReturnTime = '';
    this.notes              = '';
  }
}
<div class="flex flex-col h-screen w-screen overflow-hidden bg-[#F0F2F5] font-inter text-xs">

  <!-- TOP HEADER (full width, like USYS) -->
  <header class="h-12 bg-white border-b border-slate-200 flex items-center px-4 flex-shrink-0 gap-4">
    <div class="flex flex-col leading-none w-36 flex-shrink-0">
      <span class="text-[8px] text-slate-400 uppercase tracking-widest">Kristu Jayanti</span>
      <img src="assets/usys-logo.png" alt="USYS" class="h-5 object-contain object-left mt-0.5" />
    </div>
    <div class="flex-1 flex justify-center">
      <img src="assets/kjc-banner.png" alt="Kristu Jayanti University" class="h-7 object-contain" />
    </div>
    <span class="text-[10px] text-slate-400 w-36 text-right flex-shrink-0">Hi, Abin Xavier</span>
  </header>

  <!-- BELOW HEADER: sidebar + content -->
  <div class="flex flex-1 overflow-hidden">

  <!-- SIDEBAR -->
  <aside class="bg-white border-r border-slate-200 flex flex-col flex-shrink-0 transition-all duration-200 overflow-hidden"
    [class.w-12]="!sidebarOpen" [class.w-44]="sidebarOpen" (click)="$event.stopPropagation()">

    <!-- Collapsed: icon button -->
    <div *ngIf="!sidebarOpen" class="flex flex-col items-center py-3">
      <button class="flex flex-col items-center gap-1 w-10 py-2 rounded-lg bg-black text-white hover:bg-slate-800 transition-colors duration-150"
        (click)="sidebarOpen = true">
        <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-4 h-4">
          <path stroke-linecap="round" stroke-linejoin="round" d="M20.25 7.5l-.625 10.632a2.25 2.25 0 0 1-2.247 2.118H6.622a2.25 2.25 0 0 1-2.247-2.118L3.75 7.5M10 11.25h4M3.375 7.5h17.25c.621 0 1.125-.504 1.125-1.125v-1.5c0-.621-.504-1.125-1.125-1.125H3.375c-.621 0-1.125.504-1.125 1.125v1.5c0 .621.504 1.125 1.125 1.125Z"/>
        </svg>
        <span class="text-[8px] font-medium leading-none">Assets</span>
      </button>
    </div>

    <!-- Expanded: full panel -->
    <ng-container *ngIf="sidebarOpen">
      <div class="flex items-center justify-between px-3 py-3 border-b border-slate-100">
        <span class="text-xs font-semibold text-slate-800 whitespace-nowrap">Assets</span>
        <button class="text-slate-400 hover:text-slate-700 transition-colors" (click)="sidebarOpen = false">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-3.5 h-3.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5"/>
          </svg>
        </button>
      </div>
      <div class="px-3 py-2 border-b border-slate-100">
        <div class="flex items-center gap-1.5 bg-slate-50 border border-slate-200 rounded-md px-2 h-7">
          <svg fill="none" viewBox="0 0 24 24" stroke="#AEAEAE" stroke-width="2" class="w-3 h-3 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"/>
          </svg>
          <span class="text-[10px] text-slate-400">Search menu</span>
        </div>
      </div>
      <nav class="flex flex-col px-2 py-2 gap-0.5">
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToDashboard()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M3.75 6A2.25 2.25 0 0 1 6 3.75h2.25A2.25 2.25 0 0 1 10.5 6v2.25a2.25 2.25 0 0 1-2.25 2.25H6a2.25 2.25 0 0 1-2.25-2.25V6ZM3.75 15.75A2.25 2.25 0 0 1 6 13.5h2.25a2.25 2.25 0 0 1 2.25 2.25V18a2.25 2.25 0 0 1-2.25 2.25H6A2.25 2.25 0 0 1 3.75 18v-2.25ZM13.5 6a2.25 2.25 0 0 1 2.25-2.25H18A2.25 2.25 0 0 1 20.25 6v2.25A2.25 2.25 0 0 1 18 10.5h-2.25a2.25 2.25 0 0 1-2.25-2.25V6ZM13.5 15.75a2.25 2.25 0 0 1 2.25-2.25H18a2.25 2.25 0 0 1 2.25 2.25V18A2.25 2.25 0 0 1 18 20.25h-2.25A2.25 2.25 0 0 1 13.5 18v-2.25Z"/>
          </svg>
          Dashboard
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToViewAssets()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M8.25 6.75h12M8.25 12h12m-12 5.25h12M3.75 6.75h.007v.008H3.75V6.75Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0ZM3.75 12h.007v.008H3.75V12Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Zm-.375 5.25h.007v.008H3.75v-.008Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z"/>
          </svg>
          View Assets
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left bg-blue-600 text-white whitespace-nowrap">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M15.75 6a3.75 3.75 0 1 1-7.5 0 3.75 3.75 0 0 1 7.5 0ZM4.501 20.118a7.5 7.5 0 0 1 14.998 0A17.933 17.933 0 0 1 12 21.75c-2.676 0-5.216-.584-7.499-1.632Z"/>
          </svg>
          Issue Asset
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToIssueLog()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M9 9l10.5-3m0 6.553v3.75a2.25 2.25 0 0 1-1.632 2.163l-1.32.377a1.803 1.803 0 1 1-.99-3.467l2.31-.66a2.25 2.25 0 0 0 1.632-2.163Zm0 0V2.25L9 5.25v10.303m0 0v3.75a2.25 2.25 0 0 1-1.632 2.163l-1.32.377a1.803 1.803 0 0 1-.99-3.467l2.31-.66A2.25 2.25 0 0 0 9 15.553Z"/>
          </svg>
          Issue Log
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToReturnLog()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M9 15 3 9m0 0 6-6M3 9h12a6 6 0 0 1 0 12h-3"/>
          </svg>
          Return Log
        </button>
        <button class="flex items-center gap-2 px-2 py-2 rounded-md text-[11px] font-medium w-full text-left text-slate-600 hover:bg-slate-100 transition-colors duration-150 whitespace-nowrap" (click)="goToReports()">
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.8" class="w-3.5 h-3.5 flex-shrink-0">
            <path stroke-linecap="round" stroke-linejoin="round" d="M3 13.125C3 12.504 3.504 12 4.125 12h2.25c.621 0 1.125.504 1.125 1.125v6.75C7.5 19.496 6.996 20 6.375 20h-2.25A1.125 1.125 0 0 1 3 18.875v-5.75Zm7.5-5.25c0-.621.504-1.125 1.125-1.125h2.25c.621 0 1.125.504 1.125 1.125v12c0 .621-.504 1.125-1.125 1.125h-2.25A1.125 1.125 0 0 1 10.5 20.875v-13Zm7.5-5.25c0-.621.504-1.125 1.125-1.125h2.25c.621 0 1.125.504 1.125 1.125v17.25c0 .621-.504 1.125-1.125 1.125h-2.25A1.125 1.125 0 0 1 18 20.875V2.625Z"/>
          </svg>
          Reports
        </button>
      </nav>
    </ng-container>
  </aside>

  <!-- MAIN -->
  <div class="flex flex-col flex-1 overflow-hidden">
    <div class="flex-1 overflow-y-auto p-4">

      <!-- Page header -->
      <div class="mb-4">
        <div class="flex items-center gap-1.5 text-[10px] text-slate-400 mb-1">
          <span>Apps</span>
          <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-2.5 h-2.5"><path stroke-linecap="round" stroke-linejoin="round" d="m8.25 4.5 7.5 7.5-7.5 7.5"/></svg>
          <span class="text-blue-600 font-medium">Asset Management</span>
        </div>
        <h1 class="text-sm font-semibold text-slate-800 mb-3">Asset Management</h1>
        <div class="flex gap-3">
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToDashboard()">
            <span class="text-xs font-semibold">Dashboard</span>
            <span class="text-[10px] text-slate-400 mt-1">Overview &amp; Summary</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToViewAssets()">
            <span class="text-xs font-semibold">View Assets</span>
            <span class="text-[10px] text-slate-400 mt-1">Browse all assets</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-blue-700 text-white w-44 cursor-pointer shadow-sm">
            <span class="text-xs font-bold">Issue Asset</span>
            <span class="text-[10px] text-blue-200 mt-1">Assign to a user</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToIssueLog()">
            <span class="text-xs font-semibold">Issue Log</span>
            <span class="text-[10px] text-slate-400 mt-1">View issued assets</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToReturnLog()">
            <span class="text-xs font-semibold">Return Log</span>
            <span class="text-[10px] text-slate-400 mt-1">Track returns</span>
          </div>
          <div class="flex flex-col justify-between px-4 py-3 rounded-xl bg-white text-slate-700 w-44 cursor-pointer shadow-sm hover:shadow-md transition-shadow duration-150" (click)="goToReports()">
            <span class="text-xs font-semibold">Reports</span>
            <span class="text-[10px] text-slate-400 mt-1">Asset analytics</span>
          </div>
        </div>
      </div>

      <!-- Form card -->
      <div class="bg-white rounded-xl shadow-sm p-5">
        <h1 class="text-sm font-semibold text-slate-800 mb-0.5">Issue Asset</h1>
        <p class="text-[10px] text-slate-400 mb-5">Asset Tag – {{ assetTag }}</p>

        <div class="grid grid-cols-2 gap-x-8 gap-y-4">

          <!-- LEFT -->
          <div class="flex flex-col gap-4">
            <!-- Model -->
            <div class="flex flex-col gap-1">
              <label class="text-[10px] text-slate-500 font-medium">Model</label>
              <input type="text" [placeholder]="assetModel" [(ngModel)]="model"
                class="h-8 border border-slate-200 rounded-lg px-3 text-xs text-slate-800 outline-none focus:border-blue-500 transition-colors placeholder:text-slate-400"/>
            </div>
            <!-- Asset Name -->
            <div class="flex flex-col gap-1">
              <label class="text-[10px] text-slate-500 font-medium">Asset Name</label>
              <input type="text" [placeholder]="assetName" [(ngModel)]="assetNameInput"
                class="h-8 border border-slate-200 rounded-lg px-3 text-xs text-slate-800 outline-none focus:border-blue-500 transition-colors placeholder:text-slate-400"/>
            </div>
            <!-- Status -->
            <div class="flex flex-col gap-1 relative">
              <label class="text-[10px] text-slate-500 font-medium">Status</label>
              <div class="h-8 border border-slate-200 rounded-lg px-3 flex items-center justify-between cursor-pointer hover:border-blue-400 transition-colors"
                (click)="statusOpen = !statusOpen">
                <span class="text-xs" [class.text-slate-400]="!status" [class.text-slate-800]="status">{{ status || 'Ready to Deploy' }}</span>
                <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-3 h-3 text-slate-400 transition-transform" [class.rotate-180]="statusOpen">
                  <path stroke-linecap="round" stroke-linejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5"/>
                </svg>
              </div>
              <div *ngIf="statusOpen" class="absolute top-full left-0 right-0 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg z-50 overflow-hidden">
                <button *ngFor="let s of statuses" class="block w-full text-left px-3 py-2 text-xs text-slate-700 hover:bg-blue-50 hover:text-blue-600 transition-colors"
                  [class.bg-blue-50]="status === s" [class.text-blue-600]="status === s"
                  (click)="status = s; statusOpen = false; $event.stopPropagation()">{{ s }}</button>
              </div>
            </div>
            <!-- Issue To -->
            <div class="flex flex-col gap-1">
              <label class="text-[10px] text-slate-500 font-medium">Issue To</label>
              <div class="flex gap-2">
                <button *ngFor="let opt of ['User','Asset','Location']"
                  class="flex items-center gap-1.5 px-3 h-8 rounded-lg border text-xs font-medium transition-all duration-150"
                  [class.bg-slate-800]="issueTo === opt" [class.border-slate-800]="issueTo === opt" [class.text-white]="issueTo === opt"
                  [class.border-slate-200]="issueTo !== opt" [class.text-slate-600]="issueTo !== opt" [class.hover:border-slate-400]="issueTo !== opt"
                  (click)="issueTo = opt">{{ opt }}</button>
              </div>
            </div>
            <!-- User select -->
            <div class="flex flex-col gap-1 relative">
              <label class="text-[10px] text-slate-500 font-medium">{{ issueTo }}</label>
              <div class="flex gap-2">
                <div class="flex-1 h-8 border border-slate-200 rounded-lg px-3 flex items-center justify-between cursor-pointer hover:border-blue-400 transition-colors"
                  (click)="userOpen = !userOpen">
                  <span class="text-xs" [class.text-slate-400]="!selectedUser" [class.text-slate-800]="selectedUser">{{ selectedUser || 'Select a ' + issueTo }}</span>
                  <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" class="w-3 h-3 text-slate-400 transition-transform" [class.rotate-180]="userOpen">
                    <path stroke-linecap="round" stroke-linejoin="round" d="m19.5 8.25-7.5 7.5-7.5-7.5"/>
                  </svg>
                </div>
                <button class="w-8 h-8 border border-slate-200 rounded-lg flex items-center justify-center text-slate-500 hover:border-blue-400 hover:text-blue-600 transition-colors">
                  <svg fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5" class="w-3.5 h-3.5">
                    <path stroke-linecap="round" stroke-linejoin="round" d="M12 4.5v15m7.5-7.5h-15"/>
                  </svg>
                </button>
              </div>
              <div *ngIf="userOpen" class="absolute top-full left-0 right-8 mt-1 bg-white border border-slate-200 rounded-lg shadow-lg z-50 overflow-hidden">
                <button *ngFor="let u of users" class="block w-full text-left px-3 py-2 text-xs text-slate-700 hover:bg-blue-50 hover:text-blue-600 transition-colors"
                  [class.bg-blue-50]="selectedUser === u" [class.text-blue-600]="selectedUser === u"
                  (click)="selectedUser = u; userOpen = false; $event.stopPropagation()">{{ u }}</button>
              </div>
            </div>
          </div>

          <!-- RIGHT -->
          <div class="flex flex-col gap-4">
            <!-- Issue Date -->
            <div class="flex flex-col gap-1">
              <label class="text-[10px] text-slate-500 font-medium">Issue Date</label>
              <input type="date" [(ngModel)]="issueDate"
                class="h-8 border border-slate-200 rounded-lg px-3 text-xs text-slate-800 outline-none focus:border-blue-500 transition-colors"/>
            </div>
            <!-- Return Date + Time -->
            <div class="grid grid-cols-2 gap-3">
              <div class="flex flex-col gap-1">
                <label class="text-[10px] text-slate-500 font-medium">Expected Return Date</label>
                <input type="date" [(ngModel)]="expectedReturn"
                  class="h-8 border border-slate-200 rounded-lg px-3 text-xs text-slate-800 outline-none focus:border-blue-500 transition-colors"/>
              </div>
              <div class="flex flex-col gap-1">
                <label class="text-[10px] text-slate-500 font-medium">Expected Return Time</label>
                <input type="time" [(ngModel)]="expectedReturnTime"
                  class="h-8 border border-slate-200 rounded-lg px-3 text-xs text-slate-800 outline-none focus:border-blue-500 transition-colors"/>
              </div>
            </div>
            <!-- Notes -->
            <div class="flex flex-col gap-1">
              <label class="text-[10px] text-slate-500 font-medium">Notes</label>
              <textarea [(ngModel)]="notes" rows="5"
                class="border border-slate-200 rounded-lg px-3 py-2 text-xs text-slate-800 outline-none focus:border-blue-500 transition-colors resize-none placeholder:text-slate-400"></textarea>
            </div>
          </div>

        </div>

        <!-- Actions -->
        <div class="flex justify-end gap-3 mt-5 pt-4 border-t border-slate-100">
          <button class="h-8 px-5 rounded-lg border border-slate-200 text-xs font-medium text-slate-600 hover:border-slate-400 hover:text-slate-800 transition-all duration-150 active:scale-95"
            (click)="goBack()">Cancel</button>
          <button class="h-8 px-5 rounded-lg bg-blue-600 text-white text-xs font-semibold hover:bg-blue-700 transition-all duration-150 active:scale-95"
            (click)="onSubmit()">Issue Asset</button>
        </div>
      </div>

      <!-- Issue Log Table -->
      <div class="bg-white rounded-xl shadow-sm overflow-hidden mt-4">

        <!-- Header -->
        <div class="flex items-center justify-between px-4 py-3 border-b border-slate-100">
          <div>
            <h2 class="text-xs font-semibold text-slate-800">Issue Log</h2>
            <p class="text-[10px] text-slate-400 mt-0.5">All currently issued assets · {{ totalRecords }} record{{ totalRecords !== 1 ? 's' : '' }}</p>
          </div>
          <div class="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-lg px-3 h-8 w-52 hover:border-blue-400 transition-colors">
            <svg fill="none" viewBox="0 0 24 24" stroke="#AEAEAE" stroke-width="2" class="w-3.5 h-3.5 flex-shrink-0">
              <path stroke-linecap="round" stroke-linejoin="round" d="m21 21-5.197-5.197m0 0A7.5 7.5 0 1 0 5.196 5.196a7.5 7.5 0 0 0 10.607 10.607Z"/>
            </svg>
            <input class="flex-1 bg-transparent text-xs text-slate-700 outline-none placeholder:text-slate-400"
              type="text" placeholder="Search log..." [(ngModel)]="searchQuery" (click)="$event.stopPropagation()"/>
          </div>
        </div>

        <div *ngIf="logError" class="px-4 py-3 text-xs text-red-600 bg-red-50">{{ logError }}</div>

        <div *ngIf="isLoadingLog && !logError" class="flex items-center justify-center py-12 gap-2 text-slate-400">
          <svg class="animate-spin w-4 h-4" fill="none" viewBox="0 0 24 24">
            <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/>
            <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z"/>
          </svg>
          <span class="text-xs">Loading...</span>
        </div>

        <div *ngIf="!isLoadingLog" class="grid grid-cols-5 px-4 py-2 border-b border-slate-100">
          <span class="text-[10px] text-slate-400">Asset Name</span>
          <span class="text-[10px] text-slate-400">Category</span>
          <span class="text-[10px] text-slate-400">Issued To</span>
          <span class="text-[10px] text-slate-400">Type</span>
          <span class="text-[10px] text-slate-400">Issue Date</span>
        </div>

        <div *ngIf="!isLoadingLog && filteredLog.length === 0"
          class="flex flex-col items-center justify-center py-12 gap-2 text-slate-400">
          <span class="text-xs">No issued assets found.</span>
        </div>

        <ng-container *ngIf="!isLoadingLog">
          <div *ngFor="let row of filteredLog; let i = index"
            class="grid grid-cols-5 px-4 py-2.5 border-b border-slate-50 last:border-0 hover:bg-blue-50 transition-colors"
            [class.bg-white]="i % 2 === 0"
            [class.bg-slate-50]="i % 2 !== 0">
            <span class="text-xs font-medium text-slate-800 truncate">{{ row.assetName }}</span>
            <span class="text-xs text-slate-500">{{ row.assetCategory }}</span>
            <span class="text-xs text-slate-700 truncate">{{ row.receiverName }}</span>
            <span>
              <span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-semibold"
                [ngClass]="getReceiverTypeClass(row.receiverType)">{{ row.receiverType }}</span>
            </span>
            <span class="text-xs text-slate-400">{{ row.issueDate }}</span>
          </div>
        </ng-container>

        <div *ngIf="!isLoadingLog && totalPages > 1"
          class="flex items-center justify-between px-4 py-3 border-t border-slate-100">
          <span class="text-[10px] text-slate-400">Page {{ currentPage }} of {{ totalPages }}</span>
          <div class="flex items-center gap-1">
            <button class="h-7 px-2 rounded-md text-[11px] border border-slate-200 text-slate-500 hover:bg-slate-50 disabled:opacity-40 transition-colors"
              [disabled]="currentPage === 1" (click)="prevPage()">‹ Prev</button>
            <ng-container *ngFor="let p of pageNumbers">
              <button *ngIf="p !== -1" class="h-7 w-7 rounded-md text-[11px] border transition-colors"
                [class.bg-blue-600]="p === currentPage" [class.text-white]="p === currentPage"
                [class.border-blue-600]="p === currentPage" [class.border-slate-200]="p !== currentPage"
                [class.text-slate-600]="p !== currentPage" (click)="goToPage(p)">{{ p }}</button>
              <span *ngIf="p === -1" class="text-slate-400 text-[11px] px-1">…</span>
            </ng-container>
            <button class="h-7 px-2 rounded-md text-[11px] border border-slate-200 text-slate-500 hover:bg-slate-50 disabled:opacity-40 transition-colors"
              [disabled]="currentPage === totalPages" (click)="nextPage()">Next ›</button>
          </div>
        </div>
      </div>

    </div>
    <!-- /SCROLLABLE BODY -->
    <div *ngIf="showSuccess" class="fixed inset-0 bg-black/30 flex items-center justify-center z-50">
      <div class="bg-white rounded-2xl shadow-2xl p-8 w-80 flex flex-col items-center text-center">
        <div class="w-14 h-14 rounded-full bg-green-500 flex items-center justify-center mb-4 shadow-lg shadow-green-200">
          <svg fill="none" viewBox="0 0 24 24" stroke="white" stroke-width="2.5" class="w-7 h-7">
            <path stroke-linecap="round" stroke-linejoin="round" d="M4.5 12.75l6 6 9-13.5"/>
          </svg>
        </div>
        <h2 class="text-sm font-bold text-slate-800 mb-1">Asset Issued Successfully</h2>
        <p class="text-[10px] text-slate-500 mb-5"><strong class="text-slate-700">{{ assetName }}</strong> has been issued to <strong class="text-slate-700">{{ selectedUser }}</strong>.</p>
        <div class="flex gap-2 w-full">
          <button class="flex-1 h-8 rounded-lg border border-slate-200 text-xs font-medium text-slate-600 hover:border-slate-400 transition-all active:scale-95" (click)="issueAnother()">Issue Another</button>
          <button class="flex-1 h-8 rounded-lg bg-blue-600 text-white text-xs font-semibold hover:bg-blue-700 transition-all active:scale-95" (click)="goBack()">Back to Assets</button>
        </div>
      </div>
    </div>

    <footer class="h-6 bg-[#434B57] flex items-center justify-center flex-shrink-0">
      <span class="text-[10px] text-white">© Developed by : Software Development Centre, Kristu Jayanti (Deemed to be University), Bangalore</span>
    </footer>
  </div>
